{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "How should travel time between two locations be computed from the given coordinates — as Euclidean distance divided by a constant speed (and if so, what speed, e.g., 1 unit per minute), or as Manhattan (grid) distance?"
  ],
  "rationale": "The response asks for a single policy choice regarding the method for computing travel time. Although it includes a conditional sub-question about speed, it is contingent on selecting the Euclidean option and is part of the same decision unit."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all trucks have to start at the depot and return to the depot after finishing their route, or is it acceptable for a truck to end its route at the last customer it serves?"
  ],
  "rationale": "The response asks for a single policy choice regarding truck route endpoints (return to depot vs. end at last customer), which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a truck serve customers in any order as long as each customer's time window is respected, or is there a required sequence (e.g., customers must be visited in increasing ID order)?"
  ],
  "rationale": "The response asks a single clarification question regarding the ordering constraints for customer visits."
}

